  GM.show(R.o, t0, .1);
  A(R.c, [{clipPath: r0, easing: G12.E.inout}, {clipPath: `inset(${b.y - 6}px ${600 - b.x - b.w - 6}px ${340 - b.y - b.h - 6}px ${b.x - 6}px)`, offset: .999}, {clipPath: 'inset(-200px -200px -200px -200px)'}], t0, t1 - t0, {});
  GM.pulse(Q.m, c.h, .5, 1.22);
