  GM.seq(N.c, 'transform', [[c.at(.25), 'none', G12.E.inout], [c.at(.45), 'rotate(-58deg)', G12.E.inout], [c.at(.63), 'rotate(44deg)', G12.E.inout], [c.at(.8), 'rotate(-22deg)', G12.E.inout], [c.at(.92), 'rotate(9deg)', G12.E.inout], [c.h, 'none']]);
